@push('head')<style>.investment-start-panel{background:radial-gradient(circle at 90% 10%,rgba(40,100,255,.12),transparent 35%),var(--db-panel)}.investment-plan-icon{width:62px;height:62px;border-radius:18px;display:flex;align-items:center;justify-content:center;background:rgba(40,100,255,.12);color:#4d8dff;font-size:1.55rem}.risk-pill{font-size:.64rem;font-weight:800;padding:7px 10px;border-radius:999px;border:1px solid var(--db-border);color:var(--db-muted);white-space:nowrap}.investment-facts{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.investment-facts>div{padding:14px;border:1px solid var(--db-border);border-radius:12px}.investment-facts span,.investment-facts strong{display:block}.investment-facts span{font-size:.62rem;color:var(--db-muted)}.investment-facts strong{font-size:.86rem;margin-top:5px}.balance-card{padding:16px;border-radius:14px;background:rgba(40,100,255,.08);border:1px solid rgba(40,100,255,.18)}.balance-card span,.balance-card strong{display:block}.balance-card span{font-size:.65rem;color:var(--db-muted)}.balance-card strong{font-size:1.35rem;margin-top:4px}.confirmation-box{display:flex;gap:10px;padding:12px;border-radius:12px;background:rgba(40,100,255,.05);border:1px solid var(--db-border)}.confirmation-box i{color:#4d8dff}.confirmation-box span{font-size:.65rem;color:var(--db-muted)}.investment-processing{position:fixed;inset:0;z-index:2000;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(3,7,18,.72);backdrop-filter:blur(9px);opacity:0;visibility:hidden;pointer-events:none;transition:opacity .2s ease,visibility .2s ease}.investment-processing.is-visible{opacity:1;visibility:visible;pointer-events:auto}.investment-processing-card{width:min(390px,100%);padding:30px 26px;border:1px solid rgba(90,145,255,.28);border-radius:22px;background:rgba(13,20,35,.96);box-shadow:0 24px 80px rgba(0,0,0,.45);text-align:center}.investment-loader{width:54px;height:54px;margin:0 auto 18px;position:relative}.investment-loader:before{content:"";position:absolute;inset:2px;border:3px solid rgba(77,141,255,.18);border-top-color:#4d8dff;border-right-color:#79a9ff;border-radius:50%;animation:investmentSpin .8s linear infinite}.investment-loader span{position:absolute;width:5px;height:5px;border-radius:50%;background:#fff;top:1px;left:50%;transform:translateX(-50%);box-shadow:0 0 12px #4d8dff}.investment-processing-title{font-size:1.05rem;font-weight:800;color:#fff}.investment-processing-text{margin-top:7px;font-size:.72rem;line-height:1.5;color:#9eabc2}.investment-progress{height:4px;margin-top:20px;border-radius:99px;overflow:hidden;background:rgba(255,255,255,.08)}.investment-progress span{display:block;width:35%;height:100%;border-radius:99px;background:#4d8dff;animation:investmentProgress 1.5s ease-in-out infinite}.investment-processing.is-success .investment-loader:before{animation:none;border-color:#36d399}.investment-processing.is-success .investment-loader span{background:#36d399;box-shadow:0 0 12px #36d399}.investment-processing.is-error{background:rgba(25,5,8,.78)}@keyframes investmentSpin{to{transform:rotate(360deg)}}@keyframes investmentProgress{0%{transform:translateX(-120%)}100%{transform:translateX(330%)}}@media(max-width:576px){.investment-processing-card{padding:26px 20px}}</style>@endpush
@push('scripts')<script>
document.getElementById('investForm').addEventListener('submit',async function(e){
    e.preventDefault();
    const b=document.getElementById('submitBtn'),m=document.getElementById('msg'),overlay=document.getElementById('investmentProcessing');
    b.disabled=true;
    overlay.classList.add('is-visible');
    overlay.setAttribute('aria-hidden','false');
    m.textContent='';
    try{
        const d=await api('{{ route('investments.store') }}',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(new FormData(this))});
        overlay.classList.add('is-success');
        document.querySelector('.investment-processing-text').textContent='Investment confirmed. Preparing your portfolio...';
        const delay=3000;
        setTimeout(()=>location.href=d.redirect,delay);
    }catch(x){
        overlay.classList.remove('is-visible');
        overlay.setAttribute('aria-hidden','true');
        m.innerHTML='<span class="text-danger">'+x.message+'</span>';
        b.disabled=false;
    }
});
</script>@endpush